    internal async Task SuccessIfNotNull_with_a_nullable_value_type_value_task_and_an_error_factory_returns_a_success_with_the_value_when_it_is_not_null()
    {
        var error = Error.Create("Boom.");
        var factoryCalls = 0;
        var outcome = await Result.SuccessIfNotNull(new ValueTask<int?>(5), () => { factoryCalls++; return error; });

        Assert.True(outcome.IsSuccess);
        Assert.Equal(5, outcome.GetValue());
        Assert.Equal(0, factoryCalls);
    }

    [Fact]
    internal async Task SuccessIfNotNull_with_a_nullable_value_type_value_task_and_an_error_factory_returns_a_failure_when_the_value_is_null()
    {
        var error = Error.Create("Boom.");
        var factoryCalls = 0;
        var outcome = await Result.SuccessIfNotNull(new ValueTask<int?>((int?)null), () => { factoryCalls++; return error; });

        Assert.Same(error, outcome.GetError());
        Assert.Equal(1, factoryCalls);
    }

    [Fact]
    internal void SuccessIfNotNull_with_a_nullable_value_type_value_task_and_an_error_factory_throws_when_the_errorFactory_is_null()
    {
        var error = Error.Create("Boom.");
        var exception = Record.Exception(() => { _ = Result.SuccessIfNotNull(new ValueTask<int?>(5), (Func<Error>)null!); });

        Assert.Equal("errorFactory", Assert.IsType<ArgumentNullException>(exception).ParamName);
    }
}
